INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】その背景には、気候や風土に応じて食材を長期保存する必要があったという事情がある。
【B】発酵食品は、微生物の働きを利用して食材を保存性の高いものへと変化させた食品であり、世界各地で古くから作られてきた。
【C】つまり発酵食品の多様性は、保存という共通の目的が、異なる自然環境のなかでそれぞれ異なる技術として結実した結果だといえる。
【D】では、なぜこれほど多様な発酵食品が、それぞれの地域で独自に生み出されたのだろうか。
【E】実際、湿度の高い地域では味噌や醤油のような発酵調味料が、乾燥した地域ではチーズのような乳製品が発達してきた。', NULL, '["B→D→A→E→C","B→A→D→E→C","B→D→E→A→C","B→D→A→C→E","B→E→A→D→C"]', 0, '["すべての選択肢がBから始まっており、Bの一般的な説明が文章全体の導入であることがわかる。Bの内容を受けて「では、なぜ~生み出されたのか」と問いを立てるDが続く(B→D)。その問いに対する答えとして、気候風土による保存の必要性を述べるAが続き(D→A)、具体例を挙げるEがそれを補足する(A→E)。最後に「つまり」で内容をまとめるCが結論として続く。B→D→A→E→Cを含むのはAのみであるため、正解はAとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】では、なぜ昆虫が新たな食料源として期待されているのだろうか。
【B】また、温室効果ガスの排出量も家畜に比べて格段に少ないとされる。
【C】近年、昆虫食が次世代のタンパク源として注目を集めている。
【D】こうした環境負荷の低さが、人口増加と食料危機が懸念される現代において、昆虫食を有力な選択肢として押し上げているのである。
【E】理由の一つに、牛や豚などの家畜と比べて、飼育に必要な水や飼料が少なくて済むという点が挙げられる。', NULL, '["C→E→A→B→D","C→A→E→B→D","C→A→B→E→D","C→A→E→D→B","C→B→E→A→D"]', 1, '["すべての選択肢がCから始まる。Cで昆虫食への注目を述べたのち、「では、なぜ~期待されているのか」と問いを立てるAが続く(C→A)。その理由として飼料や水の少なさを挙げるEが続き(A→E)、「また」で温室効果ガスの少なさを付け加えるBが続く(E→B)。最後に、こうした利点をまとめて結論づけるDが続く。C→A→E→B→Dを含むのはBのみであるため、正解はBとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】その結果、方言を積極的に用いた地域振興や、方言を題材にした作品も増えている。
【B】しかし近年、方言に対する評価は大きく変化しつつある。
【C】かつて方言は、教育やメディアの場で矯正されるべき対象とみなされることも少なくなかった。
【D】方言が、その土地の歴史や暮らしに根ざした固有の文化を映し出すものとして見直されるようになったのである。
【E】方言は、特定の地域で使われてきた言葉であり、しばしば標準語と対比される形で語られてきた。', NULL, '["E→B→C→D→A","E→C→D→B→A","E→C→B→D→A","E→C→B→A→D","E→D→B→C→A"]', 2, '["すべての選択肢がEから始まる。Eで方言と標準語の対比という一般的な話題を提示したのち、かつての方言の扱いを述べるCが続く(E→C)。それを「しかし」で覆し、評価の変化を示すBが続き(C→B)、その変化の具体的な内容を述べるDが続く(B→D)。最後に「その結果」として地域振興などの動きを述べるAが結論として続く。E→C→B→D→Aを含むのはCのみであるため、正解はCとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】したがって、十分な睡眠をとらないことは、単に疲労が残るだけでなく、学習内容の定着を妨げることにもつながる。
【B】日中に得た情報は、いったん脳の海馬と呼ばれる部位に一時的に保存される。
【C】そして睡眠中、とりわけ深い眠りの段階において、この情報が大脳皮質へと転送され、長期記憶として定着すると考えられている。
【D】睡眠は、単なる休息ではなく、記憶の定着に重要な役割を果たしていることが明らかになってきた。
【E】このことから、試験前に睡眠時間を削って勉強することは、必ずしも効果的とはいえないのである。', NULL, '["D→C→B→A→E","D→B→A→C→E","D→B→C→E→A","D→B→C→A→E","D→A→C→B→E"]', 3, '["すべての選択肢がDから始まる。Dで睡眠と記憶定着の関係を提示したのち、日中の情報が海馬に保存されるという仕組みを述べるBが続く(D→B)。続いて睡眠中に情報が大脳皮質へ転送されると説明するCが続き(B→C)、その帰結として睡眠不足の弊害を述べるAが続く(C→A)。最後に「このことから」として試験前の徹夜勉強への示唆を述べるEが結論として続く。D→B→C→A→Eを含むのはDのみであるため、正解はDとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】近年、都市の広場や公園といった公共空間のあり方が見直されている。
【B】このように公共空間は、単なる通過点から、地域のつながりを生み出す場へと変わりつつあるのである。
【C】実際、ベンチの配置を工夫したり、イベントを開催したりすることで、人が滞在したくなる空間づくりを進める自治体も増えている。
【D】しかし今では、人々が偶然出会い、交流するための場としての役割が重視されるようになっている。
【E】かつてこうした空間は、単に通行のための場所、あるいは整備された緑地として扱われることが多かった。', NULL, '["A→D→E→C→B","A→E→C→D→B","A→E→D→B→C","A→C→D→E→B","A→E→D→C→B"]', 4, '["すべての選択肢がAから始まる。Aで公共空間の見直しという話題を提示したのち、かつての公共空間の扱いを述べるEが続く(A→E)。それを「しかし」で転換し、交流の場としての役割を述べるDが続き(E→D)、その具体例を挙げるCが続く(D→C)。最後に「このように」として全体をまとめるBが結論として続く。A→E→D→C→Bを含むのはEのみであるため、正解はEとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】そのため、森林面積の減少は、温暖化対策の観点から大きな問題とされてきた。
【B】森林は、地球温暖化の主な原因とされる二酸化炭素を吸収する働きを持つ。
【C】したがって、木材を積極的に活用することもまた、間接的な温暖化対策の一つとして注目されている。
【D】樹木は光合成によって大気中の二酸化炭素を取り込み、炭素として幹や枝に蓄える。
【E】一方で、木材として利用された後も、炭素は建材や家具のなかに長期間留まり続ける。', NULL, '["B→D→A→E→C","B→A→D→E→C","B→D→E→A→C","B→D→A→C→E","B→E→A→D→C"]', 0, '["すべての選択肢がBから始まる。Bで森林の二酸化炭素吸収作用を提示したのち、その仕組みを説明するDが続く(B→D)。続いて森林減少が問題視されてきたと述べるAが続き(D→A)、それに対して木材利用後も炭素が留まるという「一方で」の視点を示すEが続く(A→E)。最後に「したがって」で木材活用の意義をまとめるCが結論として続く。B→D→A→E→Cを含むのはAのみであるため、正解はAとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】しかし物々交換には、互いの欲しいものが一致しなければ成立しないという不便さがあった。
【B】これが、貨幣の原型であると考えられている。
【C】貨幣が広く使われる以前、人々は物々交換によって必要なものを手に入れていた。
【D】やがてこうした仲立ちの役割は、より扱いやすい金属貨幣や紙幣へと発展していった。
【E】そこで、誰もが価値を認めやすい貝殻や金属といったものが、交換の仲立ちとして使われるようになった。', NULL, '["C→E→A→B→D","C→A→E→B→D","C→A→B→E→D","C→A→E→D→B","C→B→E→A→D"]', 1, '["すべての選択肢がCから始まる。Cで物々交換の時代を述べたのち、「しかし」でその不便さを指摘するAが続く(C→A)。その不便さを解消するために貝殻や金属が使われ始めたと述べるEが続き(A→E)、「これが」と指示語で受けて貨幣の原型だと結論づけるBが続く(E→B)。最後に「やがて」で貨幣の発展を述べるDが続く。C→A→E→B→Dを含むのはBのみであるため、正解はBとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】つまり重要なのは、仕事が単純になくなるかどうかではなく、求められる能力がどう変化するかという点なのである。
【B】しかし、こうした変化は必ずしも雇用の減少だけを意味するわけではない。
【C】実際、定型的な事務作業やデータ入力といった業務は、すでにAIによって代替されつつある。
【D】AIの導入によって、これまで存在しなかった新たな職種が生まれている側面もあるからだ。
【E】AIの発展により、多くの仕事が自動化されるという議論が盛んになっている。', NULL, '["E→B→C→D→A","E→C→D→B→A","E→C→B→D→A","E→C→B→A→D","E→D→B→C→A"]', 2, '["すべての選択肢がEから始まる。Eで自動化に関する議論を提示したのち、具体例としてすでに代替されている業務を挙げるCが続く(E→C)。それを「しかし」で受け、雇用減少だけを意味しないと反論するBが続き(C→B)、その理由として新たな職種の誕生を挙げるDが続く(B→D)。最後に「つまり」で論点をまとめるAが結論として続く。E→C→B→D→Aを含むのはCのみであるため、正解はCとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】その一方で、紙の質感やページをめくる感覚を好み、あえて紙の本を選び続ける読者も少なくない。
【B】紙の本を持ち歩く必要がなくなり、一台の端末に何冊もの本を保存できるようになった。
【C】こうした利便性から、通勤中や移動中に読書をする人が増えたともいわれている。
【D】電子書籍の普及により、人々の読書のスタイルは大きく変わりつつある。
【E】つまり電子書籍の普及は、紙の本を駆逐したのではなく、読書のあり方に新たな選択肢を加えたと捉えるべきだろう。', NULL, '["D→C→B→A→E","D→B→A→C→E","D→B→C→E→A","D→B→C→A→E","D→A→C→B→E"]', 3, '["すべての選択肢がDから始まる。Dで電子書籍による読書スタイルの変化を提示したのち、その具体的な利点を述べるBが続く(D→B)。その利便性から読書機会が増えたと述べるCが続き(B→C)、「その一方で」紙の本を好む読者もいると対比するAが続く(C→A)。最後に「つまり」で電子書籍普及の意味をまとめるEが結論として続く。D→B→C→A→Eを含むのはDのみであるため、正解はDとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】都市部における交通渋滞は、長年にわたり大きな課題とされてきた。
【B】このように渋滞対策は、道路を増やす発想から、車の利用を減らす発想へと転換しつつある。
【C】そこで近年では、公共交通機関の利便性を高め、自動車の利用そのものを減らそうとする発想が広がっている。
【D】しかし道路を増やしても、かえって交通量そのものが増加し、渋滞が解消されない場合があることが分かってきた。
【E】その解決策として、これまでは道路の拡張や新設が中心的な手段とされてきた。', NULL, '["A→D→E→C→B","A→E→C→D→B","A→E→D→B→C","A→C→D→E→B","A→E→D→C→B"]', 4, '["すべての選択肢がAから始まる。Aで交通渋滞という課題を提示したのち、従来の解決策である道路拡張について述べるEが続く(A→E)。それを「しかし」で覆し、道路拡張だけでは解消しない場合があると指摘するDが続き(E→D)、「そこで」新たな発想として公共交通機関の活用を挙げるCが続く(D→C)。最後に「このように」として発想の転換をまとめるBが結論として続く。A→E→D→C→Bを含むのはEのみであるため、正解はEとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】例えば、速いテンポの曲は興奮や高揚感を、ゆっくりとしたテンポの曲は安らぎや悲しみを呼び起こしやすいとされる。
【B】音楽を聴くと感情が動かされるのはなぜだろうか。
【C】つまり音楽が呼び起こす感情は、音そのものの性質と、聴き手個人の経験の両方によって形づくられているのである。
【D】その理由の一つに、音楽が持つテンポや音の高低が、脳の情動をつかさどる部位を刺激するという仕組みがある。
【E】さらに、過去に聴いた音楽と結びついた個人的な記憶も、感情の動きに影響を与える。', NULL, '["B→D→A→E→C","B→A→D→E→C","B→D→E→A→C","B→D→A→C→E","B→E→A→D→C"]', 0, '["すべての選択肢がBから始まる。Bで音楽と感情の関係についての問いを提示したのち、その理由となる仕組みを説明するDが続く(B→D)。「例えば」で具体例を挙げるAが続き(D→A)、「さらに」で別の要因である個人的な記憶を付け加えるEが続く(A→E)。最後に「つまり」で両方の要因をまとめるCが結論として続く。B→D→A→E→Cを含むのはAのみであるため、正解はAとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】こうした状況のなか、地域コミュニティの役割が改めて注目されている。
【B】これらの取り組みは、孤立を防ぎ、日常のちょっとした異変に早く気づくことにもつながる。
【C】日本では高齢化が急速に進み、一人暮らしの高齢者も増加している。
【D】このように地域とのつながりは、高齢者が安心して暮らし続けるための重要な支えとなっているのである。
【E】例えば、近隣住民同士の見守り活動や、高齢者が気軽に立ち寄れる居場所づくりが各地で進められている。', NULL, '["C→E→A→B→D","C→A→E→B→D","C→A→B→E→D","C→A→E→D→B","C→B→E→A→D"]', 1, '["すべての選択肢がCから始まる。Cで高齢化の進行という現状を述べたのち、「こうした状況のなか」と受けて地域コミュニティの役割に言及するAが続く(C→A)。「例えば」で具体的な取り組みを挙げるEが続き(A→E)、その効果を述べるBが続く(E→B)。最後に「このように」として地域とのつながりの意義をまとめるDが結論として続く。C→A→E→B→Dを含むのはBのみであるため、正解はBとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】そのため今では、観光客の数を追い求めるだけでなく、地域の暮らしと両立できる観光のあり方が模索されている。
【B】しかし観光客の急増は、渋滞やごみの増加、住民の生活環境の悪化といった問題を引き起こすこともある。
【C】観光客が増えれば、宿泊や飲食、土産物といった関連産業に経済効果が波及する。
【D】こうした状況は、いわゆる観光公害と呼ばれ、各地で対応が求められるようになった。
【E】観光は、地域経済を活性化させる手段として、多くの自治体が力を入れてきた分野である。', NULL, '["E→B→C→D→A","E→C→D→B→A","E→C→B→D→A","E→C→B→A→D","E→D→B→C→A"]', 2, '["すべての選択肢がEから始まる。Eで観光による地域経済活性化という趣旨を提示したのち、その経済効果を具体的に説明するCが続く(E→C)。それを「しかし」で転換し、観光客急増の弊害を指摘するBが続き(C→B)、「こうした状況」を観光公害と名付けるDが続く(B→D)。最後に「そのため」として今後のあり方を述べるAが結論として続く。E→C→B→D→Aを含むのはCのみであるため、正解はCとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】そこで、オンラインと対面を組み合わせたハイブリッド型の授業を取り入れる動きも広がっている。
【B】場所を問わず授業を受けられることは、通学や通勤が困難な人にとって大きな利点である。
【C】一方で、対面授業に比べて、学習者同士の交流や、講師からの細やかな指導が不足しがちだという指摘もある。
【D】インターネット環境の整備が進むにつれ、オンライン教育を導入する学校や企業が増えている。
【E】このように教育の形は、オンライン化を経て、両者の利点を組み合わせる方向へと進みつつある。', NULL, '["D→C→B→A→E","D→B→A→C→E","D→B→C→E→A","D→B→C→A→E","D→A→C→B→E"]', 3, '["すべての選択肢がDから始まる。Dでオンライン教育の普及を提示したのち、その利点を述べるBが続く(D→B)。「一方で」課題を指摘するCが続き(B→C)、「そこで」対応策としてハイブリッド型授業を挙げるAが続く(C→A)。最後に「このように」として教育の方向性をまとめるEが結論として続く。D→B→C→A→Eを含むのはDのみであるため、正解はDとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】地域通貨とは、特定の地域内でのみ使用できる、法定通貨とは異なる通貨のことである。
【B】つまり地域通貨は、お金の流れを地域内にとどめることで、地域経済を支える工夫の一つだといえる。
【C】こうした仕組みによって、地域内の店舗や事業者の売り上げが増え、地域経済が循環しやすくなる。
【D】例えば、地域通貨で買い物をすると割引が受けられるなど、利用者にとってのメリットも用意されていることが多い。
【E】地域通貨は、その地域内での消費を促し、お金が地域外に流出することを防ぐ役割を果たす。', NULL, '["A→D→E→C→B","A→E→C→D→B","A→E→D→B→C","A→C→D→E→B","A→E→D→C→B"]', 4, '["すべての選択肢がAから始まる。Aで地域通貨の定義を提示したのち、その役割を説明するEが続く(A→E)。「例えば」で具体的な利用者メリットを挙げるDが続き(E→D)、「こうした仕組みによって」と受けて地域経済への効果を述べるCが続く(D→C)。最後に「つまり」で地域通貨の意義をまとめるBが結論として続く。A→E→D→C→Bを含むのはEのみであるため、正解はEとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】しかし開発や気候変動の影響により、多くの種が絶滅の危機にさらされている。
【B】生物多様性とは、生態系や種、遺伝子といった、さまざまなレベルでの生命の多様さを指す言葉である。
【C】だからこそ、個々の種を守ることは、生態系全体を守ることと切り離せない問題なのである。
【D】この多様性が保たれていることは、生態系が安定して機能するための基盤となっている。
【E】一つの種が失われることは、それに関わる生態系全体のバランスを崩すことにもつながりかねない。', NULL, '["B→D→A→E→C","B→A→D→E→C","B→D→E→A→C","B→D→A→C→E","B→E→A→D→C"]', 0, '["すべての選択肢がBから始まる。Bで生物多様性の定義を提示したのち、その意義を述べるDが続く(B→D)。それを「しかし」で転換し、種の絶滅危機を指摘するAが続き(D→A)、種が失われることの影響を述べるEが続く(A→E)。最後に「だからこそ」として結論づけるCが続く。B→D→A→E→Cを含むのはAのみであるため、正解はAとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】優れた戦略とは、単に相手の弱点を突くことだけを指すのではない。
【B】そのためには、試合展開に応じて柔軟に戦術を切り替える判断力が求められる。
【C】スポーツの試合において、個々の選手の能力だけでなく、戦略の巧拙が勝敗を左右することがある。
【D】つまり戦略の本質は、固定された作戦を貫くことではなく、状況に応じた最適解を選び続けることにあるといえる。
【E】自チームの強みを最大限に発揮できる状況を、いかにつくり出すかという視点も欠かせない。', NULL, '["C→E→A→B→D","C→A→E→B→D","C→A→B→E→D","C→A→E→D→B","C→B→E→A→D"]', 1, '["すべての選択肢がCから始まる。Cで戦略が勝敗を左右するという話題を提示したのち、優れた戦略の定義を否定形で述べるAが続く(C→A)。「という視点も欠かせない」と補足するEが続き(A→E)、「そのためには」と必要な能力を述べるBが続く(E→B)。最後に「つまり」で戦略の本質をまとめるDが結論として続く。C→A→E→B→Dを含むのはBのみであるため、正解はBとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】このように農業は、気候変動という環境の変化に合わせて、品種や栽培地を見直す転換期を迎えているのである。
【B】例えば、ある地域では高温に弱い品種の生育が難しくなり、栽培地域そのものを移す動きも出ている。
【C】気温の上昇や降水パターンの変化は、これまで栽培に適していた作物の収穫量を左右する。
【D】こうした状況に対応するため、高温や乾燥に強い品種の開発が各地で進められている。
【E】気候変動は、世界各地の農業に大きな影響を及ぼしつつある。', NULL, '["E→B→C→D→A","E→C→D→B→A","E→C→B→D→A","E→C→B→A→D","E→D→B→C→A"]', 2, '["すべての選択肢がEから始まる。Eで気候変動が農業に影響しているという話題を提示したのち、具体的な変化として気温や降水の影響を述べるCが続く(E→C)。「例えば」で具体例を挙げるBが続き(C→B)、「こうした状況に対応するため」と対策を述べるDが続く(B→D)。最後に「このように」として転換期であることをまとめるAが結論として続く。E→C→B→D→Aを含むのはCのみであるため、正解はCとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】その美しさは、実用のために繰り返し作られる中で自然と磨かれたものだと考えられている。
【B】この運動が広まる以前、美術の世界では、著名な作家による芸術作品こそが価値あるものとされていた。
【C】しかし民藝運動を唱えた人々は、無名の職人が手仕事でつくった茶碗や箒といった日用品にも、独自の美しさがあると主張した。
【D】民藝運動とは、名もなき職人たちがつくる日常の道具にこそ美が宿るとする考え方に基づく運動である。
【E】こうした考え方は、後の工芸やデザインの分野にも大きな影響を与えることになった。', NULL, '["D→C→B→A→E","D→B→A→C→E","D→B→C→E→A","D→B→C→A→E","D→A→C→B→E"]', 3, '["すべての選択肢がDから始まる。Dで民藝運動の考え方を提示したのち、それ以前の美術における価値観を述べるBが続く(D→B)。それを「しかし」で転換し、民藝運動が唱えた主張を述べるCが続き(B→C)、その美しさの由来を説明するAが続く(C→A)。最後に「こうした考え方は」として後世への影響をまとめるEが結論として続く。D→B→C→A→Eを含むのはDのみであるため、正解はDとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('tgweb_traditional_verbal', '並べ替え', NULL, '次のA〜Eの各文を、意味が通る文章になるように並べ替えた場合、最も妥当なものはどれか。

【A】宇宙開発は、かつては国家の威信をかけた競争として進められることが多かった。
【B】このように宇宙開発は、国家間の競争から協調へと、その性格を変化させてきたといえる。
【C】国際宇宙ステーションの運用は、その代表的な事例として挙げられる。
【D】そこで近年では、複数の国が資金や技術を出し合って進める国際協力の形が主流になりつつある。
【E】しかし宇宙開発には膨大な費用がかかるため、一国だけで進めることには限界がある。', NULL, '["A→D→E→C→B","A→E→C→D→B","A→E→D→B→C","A→C→D→E→B","A→E→D→C→B"]', 4, '["すべての選択肢がAから始まる。Aで宇宙開発が国家間競争であったという話題を提示したのち、「しかし」で費用面の限界を指摘するEが続く(A→E)。「そこで」と対応策として国際協力の広がりを述べるDが続き(E→D)、その代表例を挙げるCが続く(D→C)。最後に「このように」として宇宙開発の性格変化をまとめるBが結論として続く。A→E→D→C→Bを含むのはEのみであるため、正解はEとなる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型・言語: 並べ替え）');
